    private static final Path P = new Path();
    /** يرسم الأيقونة بمركز (cx,cy) وحجم size بكسل. */
    static void draw(Canvas c, String key, float cx, float cy, float size, int color, Paint p) {
        String[] ops = M.get(key); if (ops == null) return;
        float s = size / 24f; c.save(); c.translate(cx - size / 2, cy - size / 2); c.scale(s, s);
        p.setColor(color); p.setStrokeCap(Paint.Cap.ROUND); p.setStrokeJoin(Paint.Join.ROUND); p.setStrokeWidth(1.9f);
        for (String op : ops) {
            String[] t = op.split(" "); char k = t[0].charAt(0);
            if (k == 'S' || k == 'F') {
                boolean close = t[t.length - 1].equals("z"); int n = t.length - (close ? 2 : 1); P.reset();
                for (int i = 1; i + 1 <= n; i += 2) { float x = Float.parseFloat(t[i]), y = Float.parseFloat(t[i + 1]); if (i == 1) P.moveTo(x, y); else P.lineTo(x, y); }
                if (close || k == 'F') P.close();
                p.setStyle(k == 'F' ? Paint.Style.FILL : Paint.Style.STROKE); c.drawPath(P, p);
            } else if (k == 'C') { p.setStyle(Paint.Style.STROKE); c.drawCircle(Float.parseFloat(t[1]), Float.parseFloat(t[2]), Float.parseFloat(t[3]), p); }
            else if (k == 'D') { p.setStyle(Paint.Style.FILL); c.drawCircle(Float.parseFloat(t[1]), Float.parseFloat(t[2]), Float.parseFloat(t[3]), p); }
            else if (k == 'T') { p.setStyle(Paint.Style.FILL); p.setTextAlign(Paint.Align.CENTER); p.setTextSize(Float.parseFloat(t[3])); p.setTypeface(Typeface.DEFAULT_BOLD); c.drawText(t[4], Float.parseFloat(t[1]), Float.parseFloat(t[2]), p); }
        }
        c.restore();
    }
